/*
 * A267708  Triangle read by rows giving successive states of cellular
 *          automaton generated by "Rule 206" initiated with a single ON
 *          (black) cell.
 * https://oeis.org/A267708
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabf, easy
 * Formula:   a(n) = (1 + (-1)^floor(2*sqrt(n)))/2
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    /* integer square root of n by binary search */
    idx_t low = 0, high = n;
    while (low <= high) {
        idx_t mid = (low + high) >> 1;
        unsigned __int128 m2 = (unsigned __int128)mid * mid;
        if (m2 <= n)
            low = mid + 1;
        else
            high = mid - 1;
    }
    idx_t s = high;   /* floor(sqrt(n)) */
    /* compute threshold s^2 + s + 1 */
    unsigned __int128 th = (unsigned __int128)s * s + s + (unsigned __int128)1;
    /* if n < threshold => parity even => return 1; else 0 */
    return ((unsigned __int128)n < th) ? (seq_t)1 : (seq_t)0;
}
